async function chargerEnParallele(urls, chargement) {
  const promises = urls.map((url) => (async () => chargement(url))());
  const results = await Promise.allSettled(promises);

  const succes = [];
  const echecs = [];

  results.forEach((result, index) => {
    if (result.status === "fulfilled") {
      succes.push(result.value);
    } else {
      echecs.push(urls[index]);
    }
  });

  return { succes, echecs };
