    if (u === null) break;
    visited.add(u);

    const neighbors = g[u] || {};
    for (const v in neighbors) {
      if (visited.has(v)) continue;
      const alt = dist[u] + neighbors[v];
      if (alt < dist[v]) dist[v] = alt;
