  let state = "CLOSED";
  let failures = 0;
  let openedAt = 0;
  let halfOpenInProgress = false;

  return async function (...args) {
    const now = Date.now();

    if (state === "OPEN") {
      if (now - openedAt >= delaiResetMs) {
        state = "HALF_OPEN";
        halfOpenInProgress = false;
      } else {
