function dijkstra(graphe, depart) {
  const g = graphe || {};
  const nodes = new Set(Object.keys(g));

  for (const u in g) {
    const neighbors = g[u];
    if (neighbors && typeof neighbors === 'object') {
      for (const v in neighbors) nodes.add(v);
    }
  }
  nodes.add(depart);

  const dist = {};
  for (const n of nodes) dist[n] = Infinity;
  dist[depart] = 0;

  const visited = new Set();
  while (visited.size < nodes.size) {
    let u = null;
    let min = Infinity;
    for (const n of nodes) {
      if (!visited.has(n) && dist[n] < min) {
        min = dist[n];
        u = n;
      }
    }
    if (u === null) break;
    visited.add(u);

    const neighbors = g[u] || {};
    for (const v in neighbors) {
      if (visited.has(v)) continue;
      const alt = dist[u] + neighbors[v];
      if (alt < dist[v]) dist[v] = alt;
    }
  }

  return dist;
}

